<template><div class="toolbar"><a-button type="primary" @click="openForm()"><PlusOutlined/>新增同步目录</a-button><a-select v-model:value="filter" style="width:140px" :options="filters"/><span class="muted">共 {{total}} 条配置</span></div><a-card class="panel-card"><a-table :loading="loading" :data-source="paths" :columns="columns" row-key="id" :scroll="{x:1000}"><template #bodyCell="{column,record}"><template v-if="column.key==='path'"><strong>{{record.remote_path}}</strong><div class="muted">{{record.local_path}}</div></template><template v-if="column.key==='status'"><a-badge :status="record.is_running?'processing':'success'" :text="record.is_running===2?'同步中':record.is_running===1?'等待中':'空闲'"/></template><template v-if="column.key==='cron'"><a-switch :checked="record.enable_cron" @change="toggleCron(record)"/><span class="muted cron">{{record.cron}}</span></template><template v-if="column.key==='action'"><a-space><a-tooltip title="增量同步"><a-button size="small" @click="start(record)"><PlayCircleOutlined/></a-button></a-tooltip><a-tooltip v-if="record.source_type==='115'" title="全量同步"><a-popconfirm title="确定执行全量同步？" @confirm="full(record)"><a-button size="small"><SyncOutlined/></a-button></a-popconfirm></a-tooltip><a-button size="small" @click="openForm(record)"><EditOutlined/></a-button><a-popconfirm title="确定删除该目录？" @confirm="remove(record)"><a-button size="small" danger><DeleteOutlined/></a-button></a-popconfirm></a-space></template></template></a-table></a-card><a-modal v-model:open="visible" :title="editing?'编辑同步目录':'新增同步目录'" width="760px" @ok="save"><a-form layout="vertical" :model="form"><a-row :gutter="16"><a-col :span="12"><a-form-item label="来源类型"><a-select v-model:value="form.source_type" :disabled="!!editing" :options="sources"/></a-form-item></a-col><a-col :span="12"><a-form-item label="网盘账号"><a-select v-model:value="form.account_id" allow-clear :options="accountOptions"/></a-form-item></a-col></a-row><a-form-item label="源目录 ID / 路径"><a-input v-model:value="form.base_cid"/></a-form-item><a-form-item label="远端显示路径"><a-input v-model:value="form.remote_path"/></a-form-item><a-form-item label="本地 STRM 目录"><a-input v-model:value="form.local_path"/></a-form-item><a-space><a-switch v-model:checked="form.enable_cron"/>启用定时同步<a-switch v-model:checked="form.custom_config"/>自定义 STRM 配置</a-space><a-collapse v-if="form.custom_config" style="margin-top:16px"><a-collapse-panel key="custom" header="目录级 STRM 选项"><a-row :gutter="16"><a-col :span="12"><a-form-item label="STRM 地址"><a-input v-model:value="form.strm_base_url"/></a-form-item></a-col><a-col :span="12"><a-form-item label="Cron"><a-input v-model:value="form.cron"/></a-form-item></a-col></a-row></a-collapse-panel></a-collapse></a-form></a-modal></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref,watch}from'vue';import{message}from'ant-design-vue';import{PlusOutlined,PlayCircleOutlined,SyncOutlined,EditOutlined,DeleteOutlined}from'@ant-design/icons-vue';import{get,post}from'../../services/http';import type{Account,AnyMap,SyncPath}from'../../types';const paths=ref<SyncPath[]>([]),accounts=ref<Account[]>([]),loading=ref(false),total=ref(0),filter=ref(''),visible=ref(false),editing=ref<number>();const columns=[{title:'路径',key:'path'},{title:'来源',dataIndex:'source_type'},{title:'账号',dataIndex:'account_name'},{title:'状态',key:'status'},{title:'定时任务',key:'cron'},{title:'操作',key:'action',fixed:'right'}],filters=[{value:'',label:'全部来源'},...['115','baidupan','openlist','local'].map(value=>({value,label:value}))],sources=['115','baidupan','openlist','123','local'].map(value=>({value,label:value}));const defaults={id:0,source_type:'115',account_id:undefined as number|undefined,base_cid:'',remote_path:'',local_path:'',enable_cron:false,custom_config:false,strm_base_url:'',cron:'',min_video_size:-1};const form=reactive({...defaults});const accountOptions=computed(()=>accounts.value.filter(a=>a.source_type===form.source_type).map(a=>({value:a.id,label:a.name||a.username})));async function load(){loading.value=true;try{const[data,a]=await Promise.all([get<AnyMap>(`/sync/path-list?page=1&page_size=100&source_type=${filter.value}`),get<Account[]>('/account/list')]);paths.value=data.list||[];total.value=data.total||0;accounts.value=a}finally{loading.value=false}}function openForm(row?:SyncPath){editing.value=row?.id;Object.assign(form,defaults,row||{});visible.value=true}async function save(){const data={...form,account_id:form.account_id||0};await post(editing.value?'/sync/path-update':'/sync/path-add',data);visible.value=false;message.success('同步目录已保存');load()}const start=(r:SyncPath)=>post('/sync/path/start',{id:r.id}).then(()=>message.success('已加入队列'));const full=(r:SyncPath)=>post('/sync/path/full-start',{id:r.id}).then(()=>message.success('全量同步已启动'));async function toggleCron(r:SyncPath){await post('/sync/path/toggle-cron',{id:r.id});load()}async function remove(r:SyncPath){await post('/sync/path-delete',{id:r.id});load()}watch(filter,load);onMounted(load)</script><style scoped>.cron{margin-left:9px}</style>
